etter-spacing:1.5px;margin-top:19px;cursor:pointer}.text-btn:hover{color:#fff}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #ffffff15;border-bottom:1px solid #ffffff15;padding:17px 0;margin:-2px 0 20px}.result-stats b{display:block;font-family:'Playfair Display',serif;font-size:22px;color:#f1d1e8}.result-stats small{font-size:7px;letter-spacing:1px;color:#a89bb4}.mobile-pad{display:none;position:absolute;z-index:4;bottom:25px;left:20px;width:120px;height:120px;grid-template:repeat(2,1fr)/repeat(2,1fr);gap:5px;opacity:.7}.mobile-pad button{border:1px solid #ffffff48;border-radius:12px;background:#201833bb;font-size:20px;touch-action:none}.mobile-pad button:active{background:#aa7ac677}.mobile-pad button[data-dir=up]{grid-column:1;grid-row:1}.mobile-pad button[data-dir=left]{grid-column:1;grid-row:2}.mobile-pad button[data-dir=down]{grid-column:2;grid-row:2}.mobile-pad button[data-dir=right]{grid-column:2;grid-row:1}
